_R1 = [("Ang agham ay sistematikong obserbasyon ng mga likas na pangyayari upang makatuklas ng mga bagay at makagawa ng mga bagay na may kaugnayan sa kanila.", "Science is the systematic observation of natural occurrences to be able to discover and create things in relation to these occurrences."), ("Halimbawa, pinag-aaralan ng agham ang panahon at dahil dito ay nakagawa siya ng mga instrumento na makapagsasabi kung kailan darating ang isang bagyo.", "For example, science studies the weather, and because of this was able to create instruments that predict when a storm is coming."), ("Halimbawa, ang pangangailangan na makapagbigay ng impormasyon ay nagbunga sa pag-imbento ng papel, imprenta, at sa isang banda, ang telebisyon at radyo.", "For example, the need to be able to disseminate information has resulted in the invention of paper, the printing press and, on the other hand, television and radio."), ("Nakapagbubunga ang teknolohiya sa pagtaas ng produksyon at pagdali ng paggawa.", "Technology is able to result in production increase and speed of manufacturing."), ("Gamit ang makinaryang ito, maaari nang makapag-ani ng walong ektarya sa isang araw at nangangailangan lamang ng dalawa hanggang tatlong katao upang mapatakbo ito.", "Using this machine, we are able to harvest eight hectares in one day, and only two to three people are needed to operate it.")]
_R1K = [["1", "makatuklas, makagawa"], ["2", "nakagawa, makapagsasabi"], ["3", "makapagbigay"], ["4", "nakapagbubunga"], ["5", "makapag-ani"]]
